public void Rotate(int[][] m) {
    int n = m.Length;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)                 // only above the diagonal
            (m[i][j], m[j][i]) = (m[j][i], m[i][j]);
    for (int i = 0; i < n; i++)
        Array.Reverse(m[i]);                            // mirror the row
}

